import { useState, useEffect, useCallback } from 'react';
import { HiMenuAlt3, HiX } from 'react-icons/hi';

function Navbar() {
    const [showMenu, setShowMenu] = useState(false);
    const [activeSection, setActiveSection] = useState('main');
    const [scrolled, setScrolled] = useState(false);

    // Track scroll position for navbar styling
    useEffect(() => {
        const handleScroll = () => {
            const isScrolled = window.scrollY > 50;
            setScrolled(isScrolled);
        };

        window.addEventListener('scroll', handleScroll);
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    // Track active section based on scroll position
    useEffect(() => {
        const handleScrollSpy = () => {
            const sections = ['main', 'about', 'experience', 'skills', 'projects', 'achievements'];
            const scrollPosition = window.scrollY + 200;

            for (const section of sections) {
                const element = document.getElementById(section);
                if (element) {
                    const offsetTop = element.offsetTop;
                    const offsetBottom = offsetTop + element.offsetHeight;

                    if (scrollPosition >= offsetTop && scrollPosition < offsetBottom) {
                        setActiveSection(section);
                        break;
                    }
                }
            }
        };

        window.addEventListener('scroll', handleScrollSpy);
        return () => window.removeEventListener('scroll', handleScrollSpy);
    }, []);

    const scrollToComponent = (componentId) => {
        const component = document.getElementById(componentId);
        if (component) {
            component.scrollIntoView({
                behavior: 'smooth',
                duration: 2000,
                block: 'start',
                inline: 'nearest',
            });
            setShowMenu(false); // Close mobile menu after clicking
        }
    };

    const handleWindowResize = useCallback(() => {
        const screenWidth = window.innerWidth;
        if (screenWidth > 768 && showMenu) {
            setShowMenu(false);
        }
    }, [showMenu]);

    useEffect(() => {
        window.addEventListener('resize', handleWindowResize);
        return () => {
            window.removeEventListener('resize', handleWindowResize);
        };
    }, [handleWindowResize]);


    const navItems = [
        { id: 'about', label: 'About' },
        { id: 'experience', label: 'Experience' },
        { id: 'skills', label: 'Skills' },
        { id: 'projects', label: 'Projects' },
        { id: 'achievements', label: 'Achievements' }
    ];

    return (
        <nav className={`fixed top-0 left-0 right-0 z-50 glass-nav backdrop-blur-xl transition-all duration-500 ${
            scrolled 
                ? 'bg-[#0B1120]/95 border-b border-[#4F46E5]/30 shadow-2xl py-2' 
                : 'bg-[#0B1120]/80 border-b border-[#4F46E5]/20 shadow-xl py-0'
        }`}>
            {/* Enhanced background with subtle animation */}
            <div className="absolute inset-0 bg-gradient-to-r from-[#4F46E5]/5 via-transparent to-[#06B6D4]/5 animate-gradient-shift"></div>

            {/* Scroll progress indicator */}
            <div 
                className="absolute bottom-0 left-0 h-0.5 bg-gradient-to-r from-[#4F46E5] to-[#06B6D4] transition-all duration-300 z-10"
                style={{
                    width: `${Math.min((window.scrollY / (document.documentElement.scrollHeight - window.innerHeight)) * 100, 100)}%`
                }}
            ></div>

            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
                <div className="flex justify-between items-center h-16 sm:h-18">
                    {/* Enhanced Logo/Brand */}
                    <div 
                        className="text-2xl sm:text-3xl lg:text-4xl font-bold text-white relative group cursor-pointer hover-scale" 
                        onClick={() => scrollToComponent('main')}
                    >
                        <div className="relative">
                            <span className="text-gradient-animated font-black tracking-wide">
                                Amulya
                            </span>
                            <div className="absolute -inset-1 bg-gradient-to-r from-[#4F46E5]/20 to-[#06B6D4]/20 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity duration-300 blur-sm"></div>
                        </div>
                        <div className="absolute -bottom-1 left-0 w-0 h-1 bg-gradient-to-r from-[#4F46E5] to-[#06B6D4] group-hover:w-full transition-all duration-500 rounded-full"></div>

                        {/* Decorative elements */}
                        <div className="absolute -top-1 -right-2 w-2 h-2 bg-gradient-to-r from-[#4F46E5] to-[#06B6D4] rounded-full animate-pulse-subtle opacity-70"></div>
                    </div>

                    {/* Enhanced Desktop Menu with Active States */}
                    <ul className="hidden lg:flex items-center space-x-6 font-medium">
                        {navItems.map((item, index) => {
                            const isActive = activeSection === item.id;
                            return (
                                <li key={item.id}>
                                    <button
                                        className={`relative px-5 py-3 tracking-wide cursor-pointer transition-all duration-300 group text-sm font-semibold rounded-xl ${
                                            isActive 
                                                ? 'text-white bg-gradient-to-r from-[#4F46E5]/20 to-[#06B6D4]/20 border border-[#4F46E5]/30' 
                                                : 'text-gray-300 hover:text-white hover:bg-[#4F46E5]/10'
                                        }`}
                                        onClick={() => scrollToComponent(item.id)}
                                    >
                                        <span className="relative z-10">{item.label}</span>

                                        {/* Active state indicator */}
                                        {isActive && (
                                            <>
                                                <div className="absolute inset-0 bg-gradient-to-r from-[#4F46E5]/10 to-[#06B6D4]/10 rounded-xl"></div>
                                                <div className="absolute -bottom-1 left-1/2 transform -translate-x-1/2 w-1/2 h-1 bg-gradient-to-r from-[#4F46E5] to-[#06B6D4] rounded-full animate-pulse-subtle"></div>
                                            </>
                                        )}

                                        {/* Hover effects */}
                                        <div className="absolute inset-0 rounded-xl bg-gradient-to-r from-[#4F46E5]/5 to-[#06B6D4]/5 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
                                        <div className="absolute -bottom-1 left-1/2 transform -translate-x-1/2 w-0 h-0.5 bg-gradient-to-r from-[#4F46E5] to-[#06B6D4] group-hover:w-3/4 transition-all duration-300 rounded-full"></div>

                                        {/* Notification dot for active section */}
                                        {isActive && (
                                            <div className="absolute -top-1 -right-1 w-2 h-2 bg-gradient-to-r from-[#4F46E5] to-[#06B6D4] rounded-full animate-pulse"></div>
                                        )}
                                    </button>
                                </li>
                            );
                        })}
                    </ul>

                    {/* Mobile Menu Button */}
                    <button
                        className="lg:hidden text-gray-300 hover:text-[#3B82F6] transition-all duration-300 p-2 rounded-lg hover:bg-[#3B82F6]/10"
                        onClick={() => setShowMenu(!showMenu)}
                        aria-label="Toggle menu"
                    >
                        {showMenu ? <HiX size={28} /> : <HiMenuAlt3 size={28} />}
                    </button>
                </div>

                {/* Mobile Menu */}
                {showMenu && (
                    <div className="lg:hidden glass-effect bg-[#0F1419]/95 border-t border-[#3B82F6]/20 shadow-2xl backdrop-blur-xl">
                        <ul className="py-6 space-y-1">
                            <li>
                                <button
                                    className="w-full text-left block px-6 py-4 text-gray-300 text-lg font-medium hover:text-white hover:bg-[#3B82F6]/10 transition-all duration-300 cursor-pointer rounded-lg mx-2 relative group"
                                    onClick={() => scrollToComponent('about')}
                                >
                                    About
                                    <div className="absolute left-4 top-1/2 transform -translate-y-1/2 w-0 h-6 bg-[#3B82F6] group-hover:w-1 transition-all duration-300 rounded-full"></div>
                                </button>
                            </li>
                            <li>
                                <button
                                    className="w-full text-left block px-6 py-4 text-gray-300 text-lg font-medium hover:text-white hover:bg-[#3B82F6]/10 transition-all duration-300 cursor-pointer rounded-lg mx-2 relative group"
                                    onClick={() => scrollToComponent('experience')}
                                >
                                    Experience
                                    <div className="absolute left-4 top-1/2 transform -translate-y-1/2 w-0 h-6 bg-[#3B82F6] group-hover:w-1 transition-all duration-300 rounded-full"></div>
                                </button>
                            </li>
                            <li>
                                <button
                                    className="w-full text-left block px-6 py-4 text-gray-300 text-lg font-medium hover:text-white hover:bg-[#3B82F6]/10 transition-all duration-300 cursor-pointer rounded-lg mx-2 relative group"
                                    onClick={() => scrollToComponent('skills')}
                                >
                                    Skills
                                    <div className="absolute left-4 top-1/2 transform -translate-y-1/2 w-0 h-6 bg-[#3B82F6] group-hover:w-1 transition-all duration-300 rounded-full"></div>
                                </button>
                            </li>
                            <li>
                                <button
